DROP TABLE IF EXISTS sessions, notifications, receipts, payments, bill_items, bills, meter_readings, link_codes, announcements, rates, tenants, rooms, settings, users CASCADE;

CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, password_hash CHAR(60) NOT NULL, role VARCHAR(10) NOT NULL CHECK (role IN ('admin','staff')), status VARCHAR(10) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1), apartment_name VARCHAR(120) NOT NULL, address VARCHAR(255) NOT NULL, tax_id VARCHAR(13), phone VARCHAR(20) NOT NULL, office_hours VARCHAR(60) NOT NULL, due_day SMALLINT NOT NULL DEFAULT 5 CHECK (due_day BETWEEN 1 AND 28), line_test_mode BOOLEAN NOT NULL DEFAULT TRUE, line_test_user_id VARCHAR(64), updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rooms (id BIGSERIAL PRIMARY KEY, room_number VARCHAR(10) NOT NULL UNIQUE, floor SMALLINT NOT NULL CHECK (floor BETWEEN 1 AND 99), area_sqm NUMERIC(6,2) NOT NULL CHECK (area_sqm > 0), status VARCHAR(10) NOT NULL DEFAULT 'Vacant' CHECK (status IN ('Vacant','Occupied','Inactive')), water_baseline NUMERIC(12,2) NOT NULL DEFAULT 0, electric_baseline NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tenants (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), full_name VARCHAR(100) NOT NULL, phone CHAR(10) NOT NULL CHECK (phone ~ '^0[0-9]{9}$'), move_in_date DATE NOT NULL, move_out_date DATE, status VARCHAR(10) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','Inactive')), line_user_id VARCHAR(64) UNIQUE, line_linked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX uq_tenants_active_room ON tenants(room_id) WHERE status = 'Active';
CREATE TABLE rates (id BIGSERIAL PRIMARY KEY, utility_type VARCHAR(10) NOT NULL CHECK (utility_type IN ('water','electric','common')), unit_price NUMERIC(8,2) NOT NULL CHECK (unit_price > 0), effective_from DATE NOT NULL, created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (utility_type, effective_from));
CREATE TABLE meter_readings (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), period CHAR(7) NOT NULL CHECK (period ~ '^[0-9]{4}-[0-9]{2}$'), utility_type VARCHAR(10) NOT NULL CHECK (utility_type IN ('water','electric')), previous_reading NUMERIC(12,2) NOT NULL, current_reading NUMERIC(12,2) NOT NULL CHECK (current_reading >= previous_reading), meter_replaced BOOLEAN NOT NULL DEFAULT FALSE, recorded_by BIGINT NOT NULL REFERENCES users(id), recorded_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (room_id, period, utility_type));
CREATE TABLE bills (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), period CHAR(7) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft','Unpaid','Paid','Voided')), due_date DATE NOT NULL, subtotal NUMERIC(10,2) NOT NULL DEFAULT 0, total NUMERIC(10,2) NOT NULL DEFAULT 0, approved_at TIMESTAMPTZ, approved_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (room_id, period));
CREATE TABLE bill_items (id BIGSERIAL PRIMARY KEY, bill_id BIGINT NOT NULL REFERENCES bills(id) ON DELETE CASCADE, utility_type VARCHAR(10) NOT NULL CHECK (utility_type IN ('water','electric','common')), description VARCHAR(100) NOT NULL, quantity NUMERIC(12,2) NOT NULL, unit_price NUMERIC(8,2) NOT NULL, amount NUMERIC(10,2) NOT NULL, UNIQUE (bill_id, utility_type));
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, bill_id BIGINT NOT NULL UNIQUE REFERENCES bills(id), amount NUMERIC(10,2) NOT NULL, method VARCHAR(10) NOT NULL DEFAULT 'cash' CHECK (method = 'cash'), received_by BIGINT NOT NULL REFERENCES users(id), received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, voided_at TIMESTAMPTZ, void_reason VARCHAR(255));
CREATE TABLE receipts (id BIGSERIAL PRIMARY KEY, payment_id BIGINT NOT NULL UNIQUE REFERENCES payments(id), receipt_number VARCHAR(30) NOT NULL UNIQUE, printed_at TIMESTAMPTZ);
CREATE TABLE link_codes (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenants(id), code CHAR(6) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, tenant_id BIGINT REFERENCES tenants(id), bill_id BIGINT REFERENCES bills(id), type VARCHAR(20) NOT NULL CHECK (type IN ('BILL','PAID','PRE_DUE','OVERDUE','ANNOUNCEMENT')), body VARCHAR(400) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','failed','skipped_no_line')), attempt_count SMALLINT NOT NULL DEFAULT 0, send_date DATE NOT NULL DEFAULT ((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Bangkok')::date), sent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX uq_notifications_reminder ON notifications(bill_id, tenant_id, type, send_date) WHERE bill_id IS NOT NULL AND type IN ('PRE_DUE', 'OVERDUE');
CREATE TABLE announcements (id BIGSERIAL PRIMARY KEY, title VARCHAR(60) NOT NULL, body VARCHAR(400) NOT NULL, audience VARCHAR(10) NOT NULL CHECK (audience IN ('all','floors')), created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (sid VARCHAR(255) PRIMARY KEY, sess JSON NOT NULL, expire TIMESTAMP(6) NOT NULL);
